// Approach 1: Extending Thread (less preferred)
class OrderProcessor extends Thread {
    private final String orderId;

    OrderProcessor(String orderId) {
        this.orderId = orderId;
    }

    @Override
    public void run() {
        System.out.println("Processing order: " + orderId);
    }
}

// Approach 2: Implementing Runnable (preferred)
class PaymentProcessor implements Runnable {
    private final String paymentId;

    PaymentProcessor(String paymentId) {
        this.paymentId = paymentId;
    }

    @Override
    public void run() {
        System.out.println("Processing payment: " + paymentId);
    }
}

// Usage comparison
var orderThread = new OrderProcessor("ORD-123");
orderThread.start();  // Approach 1: direct start

var paymentTask = new PaymentProcessor("PAY-456");
var paymentThread = new Thread(paymentTask);
paymentThread.start();  // Approach 2: pass to Thread constructor

class DataProcessor implements Runnable {
    private final String taskName;

    DataProcessor(String taskName) {
        this.taskName = taskName;
    }

    @Override
    public void run() {
        System.out.println(taskName + " running on: " + 
                          Thread.currentThread().getName());
        for (int i = 0; i < 3; i++) {
            System.out.println(taskName + " step " + i);
        }
    }
}

public class ThreadDemo {
    public static void main(String[] args) {
        var task = new DataProcessor("Task-A");
        var thread = new Thread(task);

        System.out.println("Calling run() directly:");
        thread.run();  // Runs in main thread - NO concurrency

        System.out.println("\nCalling start():");
        thread.start();  // Creates new thread - TRUE concurrency
    }
}

// Before Java 8: Anonymous inner class (verbose)
var thread1 = new Thread(new Runnable() {
    @Override
    public void run() {
        System.out.println("Processing request in anonymous class");
    }
});
thread1.start();

// Java 8+: Lambda expression (concise)
var thread2 = new Thread(() -> {
    System.out.println("Processing request in lambda");
});
thread2.start();

// Even more concise for single statements
var thread3 = new Thread(() -> 
    System.out.println("Single line lambda"));
thread3.start();

// Method reference (when extracting to a method)
class RequestHandler {
    static void processRequest() {
        System.out.println("Processing in separate method");
    }
}
var thread4 = new Thread(RequestHandler::processRequest);
thread4.start();

import java.util.concurrent.*;

class PriceCalculator implements Callable<Double> {
    private final String productId;

    PriceCalculator(String productId) {
        this.productId = productId;
    }

    @Override
    public Double call() throws Exception {
        // Simulate expensive calculation or database call
        TimeUnit.SECONDS.sleep(2);
        return Math.random() * 100;  // computed price
    }
}

public class OrderService {
    public static void main(String[] args) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(3);

        // Submit Callable tasks
        Future<Double> price1 = executor.submit(new PriceCalculator("PROD-1"));
        Future<Double> price2 = executor.submit(new PriceCalculator("PROD-2"));

        System.out.println("Tasks submitted, continuing other work...");

        // Retrieve results - blocks if not ready
        var total = price1.get() + price2.get();
        System.out.println("Total price: " + total);

        executor.shutdown();
    }
}

import java.util.concurrent.*;

class RequestHandler implements Runnable {
    private final int requestId;

    RequestHandler(int requestId) {
        this.requestId = requestId;
    }

    @Override
    public void run() {
        System.out.println("Handling request " + requestId + 
                          " on " + Thread.currentThread().getName());
        // Simulate work
        try { TimeUnit.SECONDS.sleep(1); } catch (InterruptedException e) {}
    }
}

public class WebService {
    public static void main(String[] args) {
        // Create thread pool with 5 worker threads
        ExecutorService executor = Executors.newFixedThreadPool(5);

        // Submit 20 tasks — threads are reused
        for (int i = 1; i <= 20; i++) {
            executor.submit(new RequestHandler(i));
        }

        executor.shutdown();  // No new tasks accepted
        // executor.awaitTermination(60, TimeUnit.SECONDS);
    }
}

class HealthMonitor implements Runnable {
    @Override
    public void run() {
        while (true) {
            System.out.println("Health check: " + 
                              java.time.LocalTime.now());
            try {
                TimeUnit.SECONDS.sleep(5);
            } catch (InterruptedException e) {
                break;  // Exit gracefully on interruption
            }
        }
    }
}

public class Application {
    public static void main(String[] args) throws InterruptedException {
        var monitor = new Thread(new HealthMonitor());
        monitor.setDaemon(true);  // Must be before start()
        monitor.start();

        System.out.println("Main application running...");
        TimeUnit.SECONDS.sleep(12);  // Main work

        System.out.println("Main application done");
        // JVM exits here even though monitor is still looping
    }
}
